interface Config {
  nome: string;
  servidor: { porta: number; tls: { ativo: boolean } };
}

// O valor chega "de fora" e só depois é atribuído ao tipo.
const lido = { nome: "api", servidor: { porta: 8080, tls: { ativo: "sim" } } };

// @ts-expect-error
const cfg: Config = lido;
// TS2322: Type '{ nome: string; servidor: { porta: number; tls: { ativo: string; }; }; }'
//   is not assignable to type 'Config'.
//   The types of 'servidor.tls.ativo' are incompatible between these types.
//     Type 'string' is not assignable to type 'boolean'.

// Com o objeto literal escrito no próprio sítio, o erro desce até à propriedade:
const direto: Config = {
  nome: "api",
  servidor: {
    porta: 8080,
    // @ts-expect-error
    tls: { ativo: "sim" }, // TS2322: Type 'string' is not assignable to type 'boolean'.
  },
};

function tamanho(texto: string | undefined): number {
  // @ts-expect-error
  return texto.length; // TS18048: 'texto' is possibly 'undefined'.
}

function ler(): string | undefined {
  return undefined;
}
// @ts-expect-error
const n = ler().length; // TS2532: Object is possibly 'undefined'.

try {
  JSON.parse("{");
} catch (e) {
  // @ts-expect-error
  console.log(e.message); // TS18046: 'e' is of type 'unknown'.
}

const pessoa: { nome: string } = { nome: "Rita" };
// @ts-expect-error
pessoa.idade; // TS2339: Property 'idade' does not exist on type '{ nome: string; }'.

type Modo = "dev" | "prod";
function arrancar(modo: Modo): void {}
function somar(ns: number[]): number {
  return ns.reduce((a, b) => a + b, 0);
}

// O erro aparece no uso...
let modo = "dev"; // let alarga para string
// @ts-expect-error
arrancar(modo); // TS2345: Argument of type 'string' is not assignable to parameter of type 'Modo'.

const valores = [10, "20", 30]; // inferido como (string | number)[]
// @ts-expect-error
somar(valores);
// TS2345: Argument of type '(string | number)[]' is not assignable to parameter of type 'number[]'.
//   Type 'string | number' is not assignable to type 'number'.
//     Type 'string' is not assignable to type 'number'.

const opcoes = { modo: "dev" }; // a propriedade alarga para string
// @ts-expect-error
arrancar(opcoes.modo); // TS2345: o mesmo erro, longe da causa

// ...anotar na origem move o erro para o sítio certo:
// @ts-expect-error
const valores2: number[] = [10, "20", 30]; // TS2322: Type 'string' is not assignable to type 'number'. (coluna do "20")

const opcoes2: { modo: Modo } = { modo: "dev" };
arrancar(opcoes2.modo); // sem erro

interface Venda { produto: string; valor: number }
const vendas: Venda[] = [
  { produto: "livro", valor: 12 },
  { produto: "caneta", valor: 2 },
];

const porProduto = vendas.reduce((acc, v) => {
  // @ts-expect-error
  acc[v.produto] = (acc[v.produto] ?? 0) + v.valor;
  // TS7053: Element implicitly has an 'any' type because expression of type 'string'
  //   can't be used to index type '{}'.
  return acc;
}, {});

// Perguntar ao compilador que tipo tem porProduto:
// @ts-expect-error
const _t: never = porProduto; // TS2322: Type '{}' is not assignable to type 'never'.

// A causa está no valor inicial {}: dizer o tipo do acumulador resolve.
const porProduto2 = vendas.reduce<Record<string, number>>((acc, v) => {
  acc[v.produto] = (acc[v.produto] ?? 0) + v.valor;
  return acc;
}, {});

function formatar(v: string): string;
function formatar(v: number, casas: number): string;
function formatar(v: string | number, casas?: number): string {
  return typeof v === "number" ? v.toFixed(casas) : v;
}
// Só a primeira sobrecarga aceita 1 argumento, logo o erro é contra ela:
// @ts-expect-error
formatar(3.14159); // TS2345: Argument of type 'number' is not assignable to parameter of type 'string'.

function rotulo(v: string): string;
function rotulo(v: number): string;
function rotulo(v: bigint): string;
function rotulo(v: string | number | bigint): string {
  return String(v);
}
// @ts-expect-error
rotulo(true);
// TS2769: No overload matches this call.
//   Overload 1 of 3, '(v: string): string', gave the following error.
//     Argument of type 'boolean' is not assignable to parameter of type 'string'.
//   Overload 2 of 3, '(v: number): string', gave the following error.
//     Argument of type 'boolean' is not assignable to parameter of type 'number'.
//   Overload 3 of 3, '(v: bigint): string', gave the following error.
//     Argument of type 'boolean' is not assignable to parameter of type 'bigint'.

function par<T>(a: T, b: T): [T, T] {
  return [a, b];
}
// T fica fixado em number pelo primeiro argumento; o erro cai no segundo.
// @ts-expect-error
par(1, "dois"); // TS2345: Argument of type 'string' is not assignable to parameter of type 'number'.
const ok = par<number | string>(1, "dois"); // [string | number, string | number]

interface Utilizador { nome: string; email?: string }

function dominio(u: Utilizador): string {
  // @ts-expect-error
  return u.email.split("@")[1]; // TS18048: 'u.email' is possibly 'undefined'.
}

// Calar o erro: compila, mas rebenta em execução quando email falta.
function dominioCalado(u: Utilizador): string {
  return (u.email as string).split("@")[1];
}

// Corrigir o código: tratar o caso que o compilador apontou.
function dominioCorreto(u: Utilizador): string {
  if (u.email === undefined) return "(sem email)";
  return u.email.split("@")[1] ?? "(email inválido)";
}

