type Tema = "claro" | "escuro";

function aplicar(t: Tema): string {
  return `tema ${t} aplicado`;
}

let tema: Tema = "escuro"; // a anotação na origem impede o alargamento para string
console.log(aplicar(tema)); // tema escuro aplicado

tema = "claro";
console.log(aplicar(tema)); // tema claro aplicado

interface Linha { produto: { nome: string; preco: number } }
interface Encomenda { id: number; linhas: Linha[] }

const vindoDoFormulario = {
  id: 7,
  linhas: [{ produto: { nome: "caderno", preco: "3.50" } }],
};

// A causa está nos dados: o preço veio como texto. Converter na fronteira.
const enc: Encomenda = {
  id: vindoDoFormulario.id,
  linhas: vindoDoFormulario.linhas.map((l) => ({
    produto: { nome: l.produto.nome, preco: Number(l.produto.preco) },
  })),
};

console.log(enc.linhas[0]?.produto.preco); // 3.5

interface Registo { nivel: "info" | "erro"; texto: string }

const registos: Registo[] = [
  { nivel: "info", texto: "arranque" },
  { nivel: "erro", texto: "disco cheio" },
  { nivel: "info", texto: "pedido" },
];

// O tipo do acumulador é dito explicitamente, em vez de ser inferido de {}.
const contagem = registos.reduce<Record<Registo["nivel"], number>>(
  (acc, r) => {
    acc[r.nivel] += 1;
    return acc;
  },
  { info: 0, erro: 0 },
);

console.log(contagem.info, contagem.erro); // 2 1

// Dois parâmetros de tipo: cada lista é inferida por si e o resultado é a união.
function juntar<A, B>(a: A[], b: B[]): (A | B)[] {
  return [...a, ...b];
}

const nums = [1, 2];
const nomes = ["ana"];
const tudo = juntar(nums, nomes); // (string | number)[]

console.log(tudo); // [ 1, 2, 'ana' ]

// Quando se quer mesmo um só tipo, a versão original continua a apanhar misturas.
function juntarIguais<T>(a: T[], b: T[]): T[] {
  return [...a, ...b];
}
console.log(juntarIguais(nums, [3])); // [ 1, 2, 3 ]
